// LoadScheduledTask loads the scheduledTaskLog's ScheduledTask into the .R struct
func (os ScheduledTaskLogSlice) LoadScheduledTask(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	scheduledTasks, err := os.ScheduledTask(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range scheduledTasks {

			if !(o.ScheduledTaskID == rel.ID) {
				continue
			}

			rel.R.ScheduledTaskLogs = append(rel.R.ScheduledTaskLogs, o)

			o.R.ScheduledTask = rel
			break
		}
	}

	return nil
}

